private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int b0 = bb.get(i) & 0xFF;
    if ((b0 & 0x80) == 0) { // 1-byte ASCII
        sb.append((char) b0);
        return i + 1;
    } else if ((b0 & 0xE0) == 0xC0) { // 2-byte sequence
        int b1 = bb.get(i + 1) & 0x3F;
        int cp = ((b0 & 0x1F) << 6) | b1;
        sb.append((char) cp);
        return i + 2;
    } else if ((b0 & 0xF0) == 0xE0) { // 3-byte sequence
        int b1 = bb.get(i + 1) & 0x3F;
        int b2 = bb.get(i + 2) & 0x3F;
        int cp = ((b0 & 0x0F) << 12) | (b1 << 6) | b2;
        sb.append((char) cp);
        return i + 3;
    } else if ((b0 & 0xF8) == 0xF0) { // 4-byte sequence
        int b1 = bb.get(i + 1) & 0x3F;
        int b2 = bb.get(i + 2) & 0x3F;
        int b3 = bb.get(i + 3) & 0x3F;
        int cp = ((b0 & 0x07) << 18) | (b1 << 12) | (b2 << 6) | b3;
        cp -= 0x10000;
        char high = (char) ((cp >> 10) + 0xD800);
        char low = (char) ((cp & 0x3FF) + 0xDC00);
        sb.append(high).append(low);
        return i + 4;
    } else { // invalid start byte
        sb.append('\uFFFD');
        return i + 1;
    }
}

