public String format(LoggingEvent event){
    StringBuilder sb = new StringBuilder();
    String pat = this.pattern;
    int i = 0;
    while (i < pat.length()) {
        char c = pat.charAt(i);
        if (c == '%' && i + 1 < pat.length()) {
            char spec = pat.charAt(i + 1);
            switch (spec) {
                case 'd': {
                    String dateFormat = "yyyy-MM-dd HH:mm:ss";
                    int j = i + 2;
                    if (j < pat.length() && pat.charAt(j) == '{') {
                        int end = pat.indexOf('}', j);
                        if (end != -1) {
                            dateFormat = pat.substring(j + 1, end);
                            j = end + 1;
                        }
                    }
                    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat(dateFormat);
                    sb.append(sdf.format(new java.util.Date(event.getTimeStamp())));
                    i = j;
                    break;
                }
                case 'p':
                    sb.append(event.getLevel());
                    i += 2;
                    break;
                case 'c':
                    sb.append(event.getLoggerName());
                    i += 2;
                    break;
                case 'm':
                    sb.append(event.getMessage());
                    i += 2;
                    break;
                case 'n':
                    sb.append(System.lineSeparator());
                    i += 2;
                    break;
                case '%':
                    sb.append('%');
                    i += 2;
                    break;
                default:
                    sb.append('%').append(spec);
                    i += 2;
                    break;
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

