public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Create vertices for partition U
    java.util.List<V> uVertices = new java.util.ArrayList<>();
    for (int i = 1; i <= 3; i++) {
        V v = (V) ("U" + i);
        target.addVertex(v);
        resultMap.put("U" + i, v);
        uVertices.add(v);
    }
    // Create vertices for partition V
    java.util.List<V> vVertices = new java.util.ArrayList<>();
    for (int i = 1; i <= 3; i++) {
        V v = (V) ("V" + i);
        target.addVertex(v);
        resultMap.put("V" + i, v);
        vVertices.add(v);
    }
    // Add edges between every pair of U and V vertices
    for (V u : uVertices) {
        for (V v : vVertices) {
            target.addEdge(u, v);
        }
    }
}

