public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType){
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    java.util.Map<TypeVariable<?>, Type> map = new java.util.HashMap<>();
    java.util.Deque<Type> stack = new java.util.ArrayDeque<>();
    stack.push(targetType);
    while (!stack.isEmpty()) {
        Type t = stack.pop();
        Class<?> raw;
        if (t instanceof Class) {
            raw = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            raw = (Class<?>) ((ParameterizedType) t).getRawType();
        } else {
            continue;
        }
        TypeVariable<?>[] vars = raw.getTypeParameters();
        Type[] actuals;
        if (t instanceof ParameterizedType) {
            actuals = ((ParameterizedType) t).getActualTypeArguments();
        } else {
            actuals = new Type[0];
        }
        for (int i = 0; i < vars.length && i < actuals.length; i++) {
            map.put(vars[i], actuals[i]);
        }
        Type superT = raw.getGenericSuperclass();
        if (superT != null) {
            stack.push(superT);
        }
        for (Type iface : raw.getGenericInterfaces()) {
            stack.push(iface);
        }
    }
    for (int i = 0; i < args.length; i++) {
        Type current = args[i];
        while (current instanceof TypeVariable) {
            Type resolved = map.get(current);
            if (resolved == null) {
                return null;
            }
            current = resolved;
        }
        Class<?> c = null;
        if (current instanceof Class) {
            c = (Class<?>) current;
        } else if (current instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) current).getRawType();
            if (raw instanceof Class) {
                c = (Class<?>) raw;
            }
        }
        if (c == null) {
            return null;
        }
        result[i] = c;
    }
    return result;
}

@Override public void accept(final METRICS data) {
    if (data == null) {
        return;
    }
    // Assume METRICS has a method getKey() that uniquely identifies the metric
    String key = data.getKey();
    METRICS existing = cache.get(key);
    if (existing != null) {
        // Merge the new data with the existing value.
        // Assume METRICS has a merge(METRICS other) method that returns a merged instance.
        METRICS merged = existing.merge(data);
        cache.put(key, merged);
    } else {
        cache.put(key, data);
    }
}

