public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current mapping for the given table name.
    // It is assumed that the current mappings are stored in a field named `currentMappings`
    // of type Map<String, Mappings> within the surrounding class.
    Mappings current = currentMappings.get(tableName);
    if (current == null) {
        // No current mapping found; return an empty Mappings instance.
        return new Mappings();
    }

    // Obtain the property maps from both the current and the historical (input) mappings.
    java.util.Map<String, Object> currentProps = current.getProperties();
    java.util.Map<String, Object> inputProps = mappings.getProperties();

    // Prepare a map to hold the differences.
    java.util.Map<String, Object> diffProps = new java.util.HashMap<>();

    // Iterate over the current properties and collect those that are not present
    // in the historical mapping. Skip the special "_source" field to avoid
    // conflicts with the current index update.
    for (java.util.Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String key = entry.getKey();
        if ("_source".equals(key)) {
            continue;
        }
        if (!inputProps.containsKey(key)) {
            diffProps.put(key, entry.getValue());
        }
    }

    // Construct the resulting Mappings object with only the differing fields.
    Mappings diff = new Mappings();
    diff.setProperties(diffProps);
    return diff;
}

