private void pop(final String descriptor) {
    int i = 0;
    int len = descriptor.length();
    if (len == 0) {
        return;
    }
    if (descriptor.charAt(0) == '(') {
        // Method descriptor: pop argument types only
        i = 1;
        while (i < len && descriptor.charAt(i) != ')') {
            // Skip one type descriptor
            char c = descriptor.charAt(i);
            if (c == '[') {
                // Skip all '[' characters
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= len) break;
                c = descriptor.charAt(i);
            }
            if (c == 'L') {
                // Object type: skip until ';'
                int semicolon = descriptor.indexOf(';', i);
                if (semicolon == -1) {
                    // Malformed descriptor; stop processing
                    break;
                }
                i = semicolon + 1;
            } else {
                // Primitive type: single character
                i++;
            }
            // Pop one type from the output frame stack
            outputFrameStack.pop();
        }
        // Return type (after ')') is ignored
    } else {
        // Single type descriptor: pop it
        char c = descriptor.charAt(i);
        if (c == '[') {
            // Skip all '[' characters
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= len) return;
            c = descriptor.charAt(i);
        }
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', i);
            if (semicolon == -1) return;
            i = semicolon + 1;
        } else {
            i++;
        }
        outputFrameStack.pop();
    }
}

@Override public void write(final byte b[],final int off,final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("b is null");
    }
    if (off < 0 || len < 0 || off > b.length - len) {
        throw new IndexOutOfBoundsException("off=" + off + ", len=" + len + ", b.length=" + b.length);
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        grow(newCount);
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null) {
