private boolean containsAllFields(Fields fields){
    if (fields == null) {
        return false;
    }
    // If Fields implements Map, iterate over its keys
    if (fields instanceof java.util.Map<?,?>) {
        java.util.Map<?,?> map = (java.util.Map<?,?>) fields;
        for (Object keyObj : map.keySet()) {
            if (!(keyObj instanceof String)) {
                return false;
            }
            String key = (String) keyObj;
            if (!properties.containsKey(key)) {
                return false;
            }
        }
        return true;
    }
    // Fallback: try to obtain a collection of field names via a method named getFields()
    try {
        java.lang.reflect.Method getFieldsMethod = fields.getClass().getMethod("getFields");
        Object result = getFieldsMethod.invoke(fields);
        if (result instanceof java.util.Collection<?>) {
            java.util.Collection<?> col = (java.util.Collection<?>) result;
            for (Object obj : col) {
                if (!(obj instanceof String)) {
                    return false;
                }
                String key = (String) obj;
                if (!properties.containsKey(key)) {
                    return false;
                }
            }
            return true;
        }
    } catch (Exception e) {
        // ignore any reflection errors
    }
    return false;
}

