@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (type == Character.class || type == char.class) {
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String s = (String) value;
            if (s.length() == 1) {
                return s.charAt(0);
            } else {
                throw new IllegalArgumentException("Cannot convert String to Character: length != 1");
            }
        }
        if (value instanceof Number) {
            int intVal = ((Number) value).intValue();
            return (char) intVal;
        }
        if (value instanceof Boolean) {
            return ((Boolean) value) ? '1' : '0';
        }
        // Fallback: use toString and take first character if length is 1
        String s = value.toString();
        if (s.length() == 1) {
            return s.charAt(0);
        }
    }
    throw new IllegalArgumentException("Cannot convert " + value.getClass().getName() + " to Character");
}

