public final byte[] toByteArray() {
    // If there are no buffers, return an empty array
    if (buffers == null || buffers.isEmpty()) {
        return new byte[0];
    }

    // Compute the total size of all buffers
    int totalSize = 0;
    for (byte[] buf : buffers) {
        if (buf != null) {
            totalSize += buf.length;
        }
    }

    // Allocate the result array
    byte[] result = new byte[totalSize];

    // Copy each buffer into the result array
    int offset = 0;
    for (byte[] buf : buffers) {
        if (buf != null) {
            System.arraycopy(buf, 0, result, offset, buf.length);
            offset += buf.length;
        }
    }

    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                // Trailing backslash, treat as literal
                sb.append('\\');
                break;
            }
            char next = str.charAt(i + 1);
            // Handle escaped backslash
            if (next == '\\') {
                sb.append('\\');
                i++; // skip the escaped backslash
                continue;
            }
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    if (i + 5 >= len) {
                        throw new IllegalArgumentException("Incomplete Unicode escape sequence at index " + i);
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid Unicode escape sequence: \\u" + hex, e);
                    }
                    i += 5; // skip \uXXXX
                    break;
                default:
                    // Octal escape: up to three octal digits (0-7)
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int end = j;
                        while (end < len && end - j < 3 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                            end++;
                        }
                        String oct = str.substring(j, end);
                        try {
                            int code = Integer.parseInt(oct, 8);
                            sb.append((char) code);
                        } catch (NumberFormatException e) {
                            throw new IllegalArgumentException("Invalid octal escape sequence: \\" + oct, e);
                        }
                        i = end - 1; // adjust index
                    } else {
                        // Unrecognized escape, keep as is
                        sb.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

