    if (!root.isActive()) {
        root = null;
        return 1;
    }
    return removeUnusedNodesRecursive(root);
}

private int removeUnusedNodesRecursive(Category node) {
    int removed = 0;
    List<Category> children = node.getChildren();
    Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (!child.isActive()) {
            it.remove();
            removed++;
        } else {
            removed += removeUnusedNodesRecursive(child);
        }
    }
    return removed;
