final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    // Locate the start of the CONSTANT_Utf8 entry
    int offset = constantPoolOffsets[constantPoolEntryIndex];
    // Verify that the tag is 1 (CONSTANT_Utf8)
    if (classFileBuffer[offset] != 1) {
        throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    // Read the length of the UTF-8 string (2 bytes, big-endian)
    int length = ((classFileBuffer[offset + 1] & 0xFF) << 8) | (classFileBuffer[offset + 2] & 0xFF);
    // The UTF-8 bytes start immediately after the length field
    int byteStart = offset + 3;
    // Decode the bytes into the supplied char buffer
    java.nio.ByteBuffer byteBuf = java.nio.ByteBuffer.wrap(classFileBuffer, byteStart, length);
    java.nio.CharBuffer charBuf = java.nio.CharBuffer.wrap(charBuffer);
    java.nio.charset.CharsetDecoder decoder = java.nio.charset.StandardCharsets.UTF_8.newDecoder();
    decoder.decode(byteBuf, charBuf, true);
    decoder.flush(charBuf);
    int charsRead = charBuf.position();
    // Construct and return the String from the decoded characters
    return new String(charBuffer, 0, charsRead);
}

