private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator starting at the given node and moving in the specified direction
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the start node is the stop node, return immediately
    if (start.equals(stop)) {
        return circ;
    }

    // Traverse the outer face until we reach the stop node or find a node satisfying the predicate
    while (!circ.getNode().equals(stop)) {
        if (predicate.test(circ.getNode())) {
            return circ;
        }
        circ.next();
    }

    // At this point, circ points to the stop node
    return circ;
}

