protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return null;
    }
    // Build adjacency map for quick lookup
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour){
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(e);
    }
    // Choose an arbitrary start vertex
    V startVertex = adjacency.keySet().iterator().next();
    List<E> edgeList = new ArrayList<>();
    V current = startVertex;
    Set<E> remaining = new HashSet<>(tour);
    while (!remaining.isEmpty()){
        List<E> edges = adjacency.get(current);
        if (edges == null){
            break;
        }
        E chosen = null;
        for (E e : edges){
            if (!remaining.contains(e)){
                continue;
            }
            if (graph.isDirected()){
                if (graph.getEdgeSource(e).equals(current)){
                    chosen = e;
                    break;
                }
            } else {
                chosen = e;
                break;
            }
        }
        if (chosen == null){
            break;
        }
        edgeList.add(chosen);
        remaining.remove(chosen);
        V source = graph.getEdgeSource(chosen);
        V target = graph.getEdgeTarget(chosen);
        adjacency.get(source).remove(chosen);
        adjacency.get(target).remove(chosen);
        if (graph.isDirected()){
            current = graph.getEdgeTarget(chosen);
        } else {
            current = source.equals(current) ? target : source;
        }
    }
    V endVertex = current;
    double weight = 0.0;
    for (E e : edgeList){
        weight += graph.getEdgeWeight(e);
    }
    return new GraphWalk<>(graph, startVertex, endVertex, edgeList, weight);
}

