int addConstantNameAndType(final String name, final String descriptor){
    // Search for an existing CONSTANT_NameAndType_info with the same name and descriptor
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantInfo ci = constantPool.get(i);
        if (ci instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo cnat = (ConstantNameAndTypeInfo) ci;
            if (cnat.getName().equals(name) && cnat.getDescriptor().equals(descriptor)) {
                return i; // Found an identical entry, return its index
            }
        }
    }
    // No matching entry found; create a new one and add it to the pool
    ConstantNameAndTypeInfo newCnat = new ConstantNameAndTypeInfo(name, descriptor);
    constantPool.add(newCnat);
    return constantPool.size() - 1; // Return the index of the newly added entry
}

private String unescapeId(String input){
    if (input == null) return null;
    int len = input.length();
    if (len >= 2 && input.charAt(0) == '"' && input.charAt(len-1) == '"') {
        input = input.substring(1, len-1);
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case 'x':
                    if (i + 3 < input.length()) {
                        String hex = input.substring(i + 2, i + 4);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 3;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('x');
                            i++;
                        }
                    } else {
                        sb.append('\\').append('x');
                        i++;
                    }
                    break;
                case 'u':
                    if (i + 5 < input.length()) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 5;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('u');
                            i++;
                        }
                    } else {
                        sb.append('\\').append('u');
                        i++;
                    }
                    break;
                default:
                    sb.append(next);
                    i++;
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

