private boolean unlink(ListNodeImpl<E> node){
    if (node == null) return false; // defensive check, though node is expected non‑null
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev != null) {
        prev.next = next;
    } else {
        head = next; // node was head
    }

    if (next != null) {
        next.prev = prev;
    } else {
        tail = prev; // node was tail
    }

    // detach the node
    node.prev = null;
    node.next = null;

    size--;
    return true;
}

