private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.size == 0) {
        return;
    }
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }
    this.size += list.size;
    list.head = null;
    list.tail = null;
    list.size = 0;
}

