public static Meteor lookup(HttpServletRequest r){
    if (r == null) {
        return null;
    }
    // 1. Check request attribute
    Object attr = r.getAttribute("meteor");
    if (attr instanceof Meteor) {
        return (Meteor) attr;
    }
    // 2. Check session attribute
    HttpSession session = r.getSession(false);
    if (session != null) {
        attr = session.getAttribute("meteor");
        if (attr instanceof Meteor) {
            return (Meteor) attr;
        }
    }
    // 3. Check cookie (optional, if Meteor can be reconstructed from a cookie value)
    Cookie[] cookies = r.getCookies();
    if (cookies != null) {
        for (Cookie cookie : cookies) {
            if ("meteor".equals(cookie.getName())) {
                // Attempt to reconstruct Meteor from cookie value if possible
                try {
                    // Assuming Meteor has a static factory method fromString(String)
                    return Meteor.fromString(cookie.getValue());
                } catch (Exception e) {
                    // If reconstruction fails, ignore and continue
                }
            }
        }
    }
    // Not found
    return null;
}

