private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    int size = vertices.size();
    if (size <= 1) return true;
    Object[] arr = vertices.toArray();
    for (int i = 0; i < size; i++) {
        V vi = (V) arr[i];
        for (int j = i + 1; j < size; j++) {
            V vj = (V) arr[j];
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    java.util.List<Integer> lowerBounds = new java.util.ArrayList<>(keys.size());
    java.util.List<K> sorted = new java.util.ArrayList<>(keys);
    sorted.sort((a, b) -> ((Comparable<K>)a).compareTo(b));
    for (K key : keys) {
        int lb = 0;
        for (int i = 0; i < sorted.size(); i++) {
            if (((Comparable<K>)sorted.get(i)).compareTo(key) >= 0) {
                lb = i;
                break;
            }
        }
        lowerBounds.add(lb);
    }
    return lowerBounds;
}

