public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    boolean isAbsolute = path.startsWith("/");
    String[] pathParts = path.split("/");
    List<String> stack = new ArrayList<>();

    // Determine base components (directory part of the path)
    int limit = pathParts.length;
    if (!path.endsWith("/")) {
        // Remove the last component (assumed to be a file)
        limit = pathParts.length - 1;
    }
    for (int i = 0; i < limit; i++) {
        if (!pathParts[i].isEmpty()) {
            stack.add(pathParts[i]);
        }
    }

    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }

    // If the result is empty but the original path was absolute, return "/"
    if (result.length() == 0 && isAbsolute) {
        result.append("/");
    }

    return result.toString();
}

