    for (Object o : array) {
        if (o != null) {
            count++;
        }
    }
    if (count == array.length) {
        // All elements are non-null; cast to String[] if possible
        return (String[]) array;
    }
    String[] result = new String[count];
    int idx = 0;
    for (Object o : array) {
