private void checkIfPackedField() throws IOException {
    // Packed repeated fields are encoded as length-delimited (wire type 2).
    // If the current field descriptor indicates a packed repeated field,
    // read the length, set a new limit, and mark that we are inside a packed field.
    if (wireType == 2 && currentFieldDescriptor != null && currentFieldDescriptor.isPacked()) {
        int length = input.readRawVarint32();
        int oldLimit = input.pushLimit(length);
        packedLimit = oldLimit;
        packed = true;
        packedFieldNumber = currentFieldNumber;
        packedFieldDescriptor = currentFieldDescriptor;
    }
}

