public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> allSnapshots = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            // Assume ThreadSnapshot has a static parse method that can create an instance from a line
            ThreadSnapshot ts = ThreadSnapshot.parse(line);
            allSnapshots.add(ts);
        }
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return allSnapshots;
    }
    List<ThreadSnapshot> filtered = new ArrayList<>();
    for (ThreadSnapshot ts : allSnapshots) {
        long tsTime = ts.getTimestamp(); // Assume ThreadSnapshot exposes its timestamp
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (tsTime >= range.getStartTime() && tsTime <= range.getEndTime()) {
                filtered.add(ts);
                break;
            }
        }
    }
    return filtered;
}
